function softBox(w,h,d){const key=[w,h,d].join(',');if(shapeCache.has(key))return shapeCache.get(key);const r=Math.min(.18,w*.24,h*.24,d*.24),geo=new THREE.BoxGeometry(w,h,d,4,4,4),pos=geo.attributes.position;for(let i=0;i<pos.count;i++){const v=new THREE.Vector3().fromBufferAttribute(pos,i);const core=new THREE.Vector3(THREE.MathUtils.clamp(v.x,-w/2+r,w/2-r),THREE.MathUtils.clamp(v.y,-h/2+r,h/2-r),THREE.MathUtils.clamp(v.z,-d/2+r,d/2-r));v.sub(core).normalize().multiplyScalar(r).add(core);pos.setXYZ(i,v.x,v.y,v.z);}geo.computeVertexNormals();shapeCache.set(key,geo);return geo;}
