function animateHuman(g,dt,distance=0){
const r=g.userData.rig;if(!r)return;
const walking=distance>0.0001;r.blend=THREE.MathUtils.damp(r.blend,walking?1:0,12,dt);r.phase+=distance*3.1;
const stride=Math.sin(r.phase),swing=stride*.65*r.blend;
r.leftLeg.rotation.x=swing;r.rightLeg.rotation.x=-swing;r.leftArm.rotation.x=-swing*.8;r.rightArm.rotation.x=swing*.8;
r.body.position.y=Math.abs(Math.sin(r.phase))*.065*r.blend+Math.sin(elapsed*2)*.012*(1-r.blend);
r.body.rotation.z=Math.sin(r.phase)*.035*r.blend;r.body.rotation.x=.055*r.blend;
r.leftArm.rotation.z=.06;r.rightArm.rotation.z=-.06;if(r.wings)r.wings.forEach((w,i)=>w.rotation.y=(i?-1:1)*(Math.sin(r.phase)*.12*r.blend+Math.sin(elapsed*2)*.025));
if(r.action>0){r.action=Math.max(0,r.action-dt);const t=1-r.action/.55;r.rightArm.rotation.x=-.3-Math.sin(t*Math.PI)*1.9;r.leftArm.rotation.x=-.25;r.body.rotation.x+=Math.sin(t*Math.PI)*.15;r.body.rotation.y=Math.sin(t*Math.PI)*-.12;}else r.body.rotation.y=0;
}
