function worldObject(t){if(!t)return null;if(t.kind==='resource')return resources.includes(t.ref)&&t.ref.g.visible?t.ref.g:null;if(t.kind==='sapling')return s.saplings.includes(t.ref)?saplingObjects.get(t.ref):null;if(t.kind==='mushroom')return !t.ref.collected?mushroomObjects.get(t.ref):null;if(t.kind==='building')return buildingGroups.get(t.id);if(t.kind==='monster')return !t.ref.dead?t.ref.g:null;if(t.kind==='island')return t.ref.g;if(t.kind==='boat')return boat?.visible?boat:null;if(t.kind==='talk')return t.ref===visitorMesh||t.ref===board||npcs.includes(t.ref)||animals.includes(t.ref)?t.ref:null;return null;}
