function clickableTargets(){if(sea)return [...monsters.filter(m=>!m.dead).map(ref=>({kind:'monster',ref})),...islands.map(ref=>({kind:'island',ref}))];return [...resources.filter(r=>r.g.visible).map(ref=>({kind:'resource',ref})),...s.saplings.map(ref=>({kind:'sapling',ref})),...s.mushrooms.filter(p=>!p.collected).map(ref=>({kind:'mushroom',ref})),...[visitorMesh,board,...npcs,...animals].filter(Boolean).map(ref=>({kind:'talk',ref})),...[...buildingGroups.keys()].map(id=>({kind:'building',id})),...(level(s,'boat')?[{kind:'boat'}]:[])];}
