function gatherResource(r){if(!resources.includes(r)||!r.g.visible||sea||Math.hypot(r.x-player.position.x,r.z-player.position.z)>2.1||harvestCD>0)return false;if(r.cool>0){toast('잠깐 기다리면 다시 모을 수 있어요.');return false;}cancelMove();player.userData.rig.action=.55;player.rotation.y=Math.atan2(r.x-player.position.x,r.z-player.position.z);const amount=r.type==='wood'?4:3;s[r.type]+=amount;s.totals[r.type]+=amount;r.cool=2;harvestCD=.3;r.g.scale.setScalar(.82);setTimeout(()=>r.g.scale.setScalar(1),130);beep(r.type==='wood'?330:440);render();save();return true;}
