renderer.domElement.onpointerdown=e=>{if(e.button!==0)return;setInputMode(touchPoint(e));renderer.domElement.focus({preventScroll:true});renderer.domElement.setPointerCapture(e.pointerId);if(touchPoint(e)){gesturePointers.set(e.pointerId,{x:e.clientX,y:e.clientY});if(gesturePointers.size>=2){if(!pinchState)beginPinch();return;}if(gestureBlocked)return;}pointerOrigin={x:e.clientX,y:e.clientY,id:e.pointerId};drag=false;lastX=e.clientX;if(canStartJoystick(e))joystick={id:e.pointerId,x:e.clientX,y:e.clientY,dx:0,dz:0,strength:0,active:false};};
renderer.domElement.onpointermove=e=>{if(gesturePointers.has(e.pointerId))gesturePointers.set(e.pointerId,{x:e.clientX,y:e.clientY});if(gesturePointers.size>=2){if(!pinchState)beginPinch();const [a,b]=[...gesturePointers.values()];const distance=Math.max(1,Math.hypot(a.x-b.x,a.y-b.y));setZoom(pinchState.zoom*pinchState.distance/distance);return;}if(gestureBlocked)return;if(joystick?.id===e.pointerId){trackJoystick(e);return;}updatePlacementPointer(e);if(!pointerOrigin||pointerOrigin.id!==e.pointerId)return;if(!drag&&Math.hypot(e.clientX-pointerOrigin.x,e.clientY-pointerOrigin.y)>6){drag=true;cancelMove();}if(drag)yaw-=(e.clientX-lastX)*.006;lastX=e.clientX;};
function endPointer(e,cancelled=false){const wasJoystick=joystick?.id===e.pointerId&&joystick.active;if(joystick?.id===e.pointerId)stopJoystick();gesturePointers.delete(e.pointerId);if(wasJoystick){pointerOrigin=null;drag=false;return;}if(gestureBlocked){if(!gesturePointers.size)resetGesture();return;}if(pointerOrigin&&pointerOrigin.id===e.pointerId){if(!cancelled&&!drag&&Math.hypot(e.clientX-pointerOrigin.x,e.clientY-pointerOrigin.y)<=6)clickGround(e);pointerOrigin=null;drag=false;}if(cancelled&&!gesturePointers.size)resetGesture();}
renderer.domElement.onpointerup=e=>endPointer(e);renderer.domElement.onpointercancel=e=>endPointer(e,true);renderer.domElement.onlostpointercapture=e=>{if(gesturePointers.has(e.pointerId))endPointer(e,true);};
renderer.domElement.onwheel=e=>{e.preventDefault();const delta=e.deltaY*(e.deltaMode===1?16:e.deltaMode===2?innerHeight:1);setZoom(zoom*Math.exp(delta*.0015));};addEventListener('blur',resetGesture);

